import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const sourcePath = path.join(ROOT, 'design-system/brand-tokens.json');
const tokens = JSON.parse(await readFile(sourcePath, 'utf8'));
const checkOnly = process.argv.includes('--check');

const kebab = (value) => value.replace(/[A-Z]/g, (letter) => `-${letter.toLowerCase()}`);
const px = (value) => `${value}px`;
const lines = [];
const push = (...items) => lines.push(...items);

function renderMiniappScss() {
    lines.length = 0;
    push('// Generated by scripts/sync-design-tokens.mjs. Do not edit.');
    for (const [name, value] of Object.entries(tokens.color)) push(`$ky-${kebab(name)}: ${value};`);
    push(
        '$ky-on-primary-divider: rgba(255, 255, 255, 0.3);',
        '$ky-primary-surface-overlay: rgba(255, 255, 255, 0.34);',
        '$ky-primary-divider: rgba(0, 98, 65, 0.14);',
        '$ky-gold-soft: $ky-yellow-soft;',
        '',
    );
    for (const [name, value] of Object.entries(tokens.radiusPx)) push(`$ky-radius-${name}: ${px(value)};`);
    push('');
    for (const [name, value] of Object.entries(tokens.spacingPx)) push(`$ky-space-${name}: ${px(value)};`);
    push(
        '',
        '$ky-shadow-card: 0 3px 0 rgba(30, 57, 50, 0.08);',
        '$ky-shadow-subtle: 0 2px 0 rgba(30, 57, 50, 0.06);',
        '$ky-shadow-raised: 0 8px 20px rgba(30, 57, 50, 0.1);',
        `$ky-font-sans: ${tokens.typography.fontFamily};`,
    );
    for (const [name, value] of Object.entries(tokens.typography.miniappSizePx)) push(`$ky-font-size-${kebab(name)}: ${px(value)};`);
    for (const [name, value] of Object.entries(tokens.typography.weight)) push(`$ky-font-weight-${name}: ${value};`);
    for (const [name, value] of Object.entries(tokens.typography.lineHeight)) push(`$ky-leading-${name}: ${value};`);
    push(
        `$ky-paragraph-spacing: $ky-${tokens.paragraph.miniappSpacingToken};`,
        `$ky-prose-spacing: $ky-${tokens.paragraph.miniappProseSpacingToken};`,
    );
    for (const [name, value] of Object.entries(tokens.motionMs)) push(`$ky-motion-${name}: ${value}ms;`);
    return `${lines.join('\n')}\n`;
}

function renderMiniappTheme() {
    const colorEntries = ['blue', 'canvas', 'danger', 'primary', 'primaryStrong', 'success', 'surface', 'textSecondary']
        .map((name) => `    ${name}: '${tokens.color[name]}',`)
        .join('\n');
    return `// Generated by scripts/sync-design-tokens.mjs. Do not edit.\nconst themeColors = Object.freeze({\n${colorEntries}\n    tab: '${tokens.color.textSecondary}',\n});\n\nconst immersivePageChrome = Object.freeze({\n    backgroundColor: themeColors.primary,\n    backgroundColorBottom: themeColors.canvas,\n    backgroundColorTop: themeColors.primary,\n    backgroundTextStyle: 'light',\n    navigationBarBackgroundColor: themeColors.primary,\n    navigationBarTextStyle: 'white',\n});\n\nconst canvasPageChrome = Object.freeze({\n    backgroundColor: themeColors.canvas,\n    backgroundColorBottom: themeColors.canvas,\n    backgroundColorTop: themeColors.canvas,\n    backgroundTextStyle: 'dark',\n});\n\nexport { canvasPageChrome, immersivePageChrome, themeColors };\n`;
}

function renderAdminCss() {
    const c = tokens.color;
    const t = tokens.typography.admin;
    return `/* Generated by scripts/sync-design-tokens.mjs. Do not edit. */\n:root {\n  --background: ${c.canvas};\n  --foreground: ${c.ink};\n  --card: ${c.surface};\n  --card-foreground: ${c.inkStrong};\n  --popover: ${c.surface};\n  --popover-foreground: ${c.inkStrong};\n  --primary: ${c.primary};\n  --primary-hover: ${c.primaryStrong};\n  --primary-foreground: ${c.onPrimary};\n  --secondary: #edf4f1;\n  --secondary-foreground: ${c.inkStrong};\n  --muted: #eef3f1;\n  --muted-foreground: ${c.textSecondary};\n  --accent: ${c.primarySoft};\n  --accent-foreground: ${c.inkStrong};\n  --destructive: ${c.danger};\n  --destructive-hover: ${c.dangerPressed};\n  --destructive-foreground: ${c.onPrimary};\n  --border: #d8e2de;\n  --input: #c8d6d1;\n  --ring: ${c.primary};\n  --sidebar: #f0f6f3;\n  --sidebar-accent: ${c.primarySoft};\n  --brand: ${c.primary};\n  --brand-foreground: ${c.onPrimary};\n  --brand-soft: ${c.primarySoft};\n  --brand-wash: #f6faf8;\n  --brand-border: ${c.primaryLine};\n  --info: ${c.blue};\n  --info-soft: ${c.blueSoft};\n  --info-wash: #f7fbfe;\n  --success: ${c.success};\n  --success-soft: ${c.successSoft};\n  --success-wash: #f7fbf8;\n  --warning: ${c.gold};\n  --warning-soft: ${c.yellowSoft};\n  --warning-wash: #fffdf3;\n  --warning-foreground: #5f4a00;\n  --danger-soft: ${c.dangerSoft};\n  --point: ${c.gold};\n  --point-soft: ${c.yellowSoft};\n  --point-border: #e4cf70;\n  --overlay: rgb(30 57 50 / 45%);\n  --on-primary-overlay: rgb(255 255 255 / 12%);\n  --ky-font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "SF Pro Text", "Segoe UI", "PingFang SC", "Microsoft YaHei", sans-serif;\n  --ky-font-size-caption: ${t.caption};\n  --ky-font-size-body: ${t.body};\n  --ky-font-size-body-lg: ${t.bodyLg};\n  --ky-font-size-title-sm: ${t.titleSm};\n  --ky-font-size-title: ${t.title};\n  --ky-font-size-heading: ${t.heading};\n  --ky-line-height-caption: ${t.captionLine};\n  --ky-line-height-body: ${t.bodyLine};\n  --ky-line-height-body-lg: ${t.bodyLgLine};\n  --ky-line-height-title: ${t.titleLine};\n  --ky-font-weight-medium: 500;\n  --ky-font-weight-semibold: 600;\n  --ky-font-weight-bold: 700;\n  --ky-paragraph-size: var(--ky-font-size-body);\n  --ky-paragraph-line-height: var(--ky-line-height-body);\n  --ky-paragraph-spacing: ${tokens.paragraph.adminSpacingRem};\n  --ky-prose-measure: ${t.proseMeasure};\n  --ky-space-unit: 0.25rem;\n  --ky-radius-sm: 0.25rem;\n  --ky-radius-md: 0.375rem;\n  --ky-radius-lg: 0.5rem;\n  --ky-shadow-sm: 0 1px 2px rgb(30 57 50 / 8%);\n  --ky-shadow-lg: 0 12px 28px rgb(30 57 50 / 14%);\n  --ky-motion-fast: ${tokens.motionMs.fast}ms;\n  --ky-motion-base: ${tokens.motionMs.base}ms;\n}\n\n@theme inline {\n  --font-sans: var(--ky-font-sans);\n  --text-xs: var(--ky-font-size-caption);\n  --text-xs--line-height: var(--ky-line-height-caption);\n  --text-sm: var(--ky-font-size-body);\n  --text-sm--line-height: var(--ky-line-height-body);\n  --text-base: var(--ky-font-size-body-lg);\n  --text-base--line-height: var(--ky-line-height-body-lg);\n  --text-lg: var(--ky-font-size-title-sm);\n  --text-lg--line-height: var(--ky-line-height-title);\n  --text-xl: var(--ky-font-size-title);\n  --text-xl--line-height: var(--ky-line-height-title);\n  --text-2xl: var(--ky-font-size-heading);\n  --text-2xl--line-height: var(--ky-line-height-title);\n  --font-weight-medium: var(--ky-font-weight-medium);\n  --font-weight-semibold: var(--ky-font-weight-semibold);\n  --font-weight-bold: var(--ky-font-weight-bold);\n  --spacing: var(--ky-space-unit);\n  --radius-sm: var(--ky-radius-sm);\n  --radius-md: var(--ky-radius-md);\n  --radius-lg: var(--ky-radius-lg);\n  --shadow-sm: var(--ky-shadow-sm);\n  --shadow-xl: var(--ky-shadow-lg);\n  --default-transition-duration: var(--ky-motion-fast);\n}\n`;
}

const outputs = new Map([
    [path.join(ROOT, 'ikanyue.taro3/src/styles/_brand.generated.scss'), renderMiniappScss()],
    [path.join(ROOT, 'ikanyue.taro3/src/styles/theme.mjs'), renderMiniappTheme()],
    [path.join(ROOT, 'ikanyue.admin/src/styles/brand.generated.css'), renderAdminCss()],
]);

let stale = false;
for (const [target, content] of outputs) {
    if (checkOnly) {
        const current = await readFile(target, 'utf8').catch(() => '');
        if (current !== content) {
            stale = true;
            console.error(`Outdated design tokens: ${path.relative(ROOT, target)}`);
        }
        continue;
    }
    await mkdir(path.dirname(target), { recursive: true });
    await writeFile(target, content);
    console.log(`Updated ${path.relative(ROOT, target)}`);
}

if (stale) process.exitCode = 1;
